function localizeList(items: string[] | undefined, language: Language) {
  if (!items?.length || language === "en") return items;
  return items.map((item) => {
    const exact = properNameTranslations[item] || parkTranslations[item];
    if (exact) return exact[language];
    let value = item;
    for (const [pattern, replacement] of phraseTranslations[language]) value = value.replace(pattern, replacement);
    return value;
  });
}

